// Oracle 表元数据：列、索引、外键、触发器、注释、DDL。
//
// 全部走 `ALL_*` 视图（当前账号有权看到的部分），不依赖 `DBA_*` / `V$*`。
// 类型文本以目录里的声明为准：驱动给出的 `VARCHAR2(n)` 按字节计，
// 会把 `VARCHAR2(24 CHAR)` 显示成 `VARCHAR2(96)`。

/// Oracle 单个 `IN (...)` 列表最多 1000 项，批量元数据查询按此切片。
const ORACLE_IN_BATCH: usize = 900;

#[derive(Clone, Debug)]
struct OracleColumnInfo {
    name: String,
    type_name: String,
    nullable: bool,
    primary_key: bool,
    comment: Option<String>,
    default_value: Option<String>,
    /// 12c+ 身份列；`GENERATED BY DEFAULT` / `GENERATED ALWAYS` 由身份列视图补全。
    identity: Option<String>,
    /// 虚拟列表达式；有值时列不可写，DDL 必须保留 `GENERATED ALWAYS AS (...)`。
    virtual_expression: Option<String>,
    primary_key_constraint: Option<String>,
}

fn oracle_load_columns(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Vec<Column>> {
    Ok(oracle_load_column_infos(connection, schema, table)?
        .into_iter()
        .map(|column| Column {
            name: column.name,
            type_name: Some(column.type_name),
            nullable: column.nullable,
            primary_key: column.primary_key,
            comment: column.comment,
        })
        .collect())
}

fn oracle_load_column_infos(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Vec<OracleColumnInfo>> {
    let query = |owner: &str, table: &str| {
        let binds = [
            OracleBindValue::Text(owner.to_string()),
            OracleBindValue::Text(table.to_string()),
        ];
        oracle_query(
            connection,
            "SELECT C.COLUMN_NAME, C.DATA_TYPE, C.DATA_LENGTH, C.CHAR_LENGTH, C.CHAR_USED, \
                    C.DATA_PRECISION, C.DATA_SCALE, C.NULLABLE, C.DATA_DEFAULT, \
                    C.VIRTUAL_COLUMN, C.IDENTITY_COLUMN, CC.COMMENTS, \
                    CASE WHEN PK.COLUMN_NAME IS NULL THEN 0 ELSE 1 END AS IS_PK, \
                    PK.CONSTRAINT_NAME \
             FROM ALL_TAB_COLS C \
             LEFT JOIN ALL_COL_COMMENTS CC \
               ON CC.OWNER = C.OWNER AND CC.TABLE_NAME = C.TABLE_NAME \
              AND CC.COLUMN_NAME = C.COLUMN_NAME \
             LEFT JOIN (SELECT CO.OWNER, CO.TABLE_NAME, CC2.COLUMN_NAME, CO.CONSTRAINT_NAME \
                        FROM ALL_CONSTRAINTS CO \
                        JOIN ALL_CONS_COLUMNS CC2 \
                          ON CC2.OWNER = CO.OWNER AND CC2.CONSTRAINT_NAME = CO.CONSTRAINT_NAME \
                        WHERE CO.CONSTRAINT_TYPE = 'P' AND CO.OWNER = :1 \
                          AND CO.TABLE_NAME = :2) PK \
               ON PK.OWNER = C.OWNER AND PK.TABLE_NAME = C.TABLE_NAME \
              AND PK.COLUMN_NAME = C.COLUMN_NAME \
             WHERE C.OWNER = :3 AND C.TABLE_NAME = :4 AND C.HIDDEN_COLUMN = 'NO' \
             ORDER BY C.COLUMN_ID",
            // `:1`/`:2` 在子查询里出现一次，`:3`/`:4` 是外层条件；驱动按出现次数校验绑定，
            // 所以同一 schema/table 各绑定两次。
            &[
                binds[0].clone(),
                binds[1].clone(),
                binds[0].clone(),
                binds[1].clone(),
            ],
        )
    };
    // 补全里的未引用表名来自 SQL 解析，Oracle 会折叠为大写后再查目录；
    // 带引号的混合大小写名（如 "Order Details"）仍按原样精确匹配。
    let actual_owner = schema.to_string();
    let mut actual_table = table.to_string();
    let mut rows = query(&actual_owner, &actual_table)?;
    if rows.is_empty() {
        let upper = table.to_uppercase();
        if upper != table {
            actual_table = upper;
            rows = query(&actual_owner, &actual_table)?;
        }
    }
    // 同义词不在 ALL_TAB_COLS 里；按目标表再查一次，补全使用同义词时仍能给出真实列。
    if rows.is_empty()
        && let Some((owner, table)) = oracle_synonym_target(connection, &actual_owner, &actual_table)
    {
        actual_table = table;
        rows = query(&owner, &actual_table)?;
    }
    if rows.is_empty() {
        return Err(Error::new(
            ErrorKind::Query,
            format!("未读取到 {schema}.{table} 的列信息（对象不存在或无权限）"),
        ));
    }
    let identities = oracle_load_identity_columns(connection, &actual_owner, &actual_table);
    let mut columns = Vec::with_capacity(rows.len());
    for row in &rows {
        let Some(name) = oracle_meta_text(row, 0) else {
            continue;
        };
        let data_type = oracle_meta_text(row, 1).unwrap_or_default();
        let data_length = oracle_meta_u64(row, 2).unwrap_or(0);
        let char_length = oracle_meta_u64(row, 3).unwrap_or(0);
        let char_used = oracle_meta_text(row, 4).unwrap_or_default();
        let precision = oracle_meta_i64(row, 5);
        let scale = oracle_meta_i64(row, 6);
        let is_virtual = oracle_meta_text(row, 9)
            .is_some_and(|value| value.eq_ignore_ascii_case("YES"));
        let default_value = oracle_meta_text(row, 8);
        let virtual_expression = if is_virtual { default_value.clone() } else { None };
        columns.push(OracleColumnInfo {
            name: name.clone(),
            type_name: oracle_column_type_name(
                &data_type,
                data_length,
                char_length,
                &char_used,
                precision,
                scale,
            ),
            nullable: oracle_meta_text(row, 7)
                .is_some_and(|value| value.eq_ignore_ascii_case("Y")),
            primary_key: oracle_meta_u64(row, 12).unwrap_or(0) != 0,
            comment: oracle_meta_text(row, 11),
            // 虚拟列的 `DATA_DEFAULT` 是表达式，不能当成 DEFAULT 再写一遍。
            default_value: if is_virtual {
                None
            } else {
                default_value.filter(|value| !value.trim().is_empty())
            },
            identity: identities.get(&name).cloned(),
            virtual_expression,
            primary_key_constraint: oracle_meta_text(row, 13),
        });
    }
    Ok(columns)
}

/// 解析私有/公共同义词指向的真实表；未命中返回 `None`。
fn oracle_synonym_target(
    connection: &OracleConnection,
    owner: &str,
    synonym: &str,
) -> Option<(String, String)> {
    let mut candidates = vec![synonym.to_string()];
    let upper = synonym.to_uppercase();
    if upper != synonym {
        candidates.push(upper);
    }
    for name in candidates {
        let rows = oracle_query(
            connection,
            "SELECT TABLE_OWNER, TABLE_NAME FROM ALL_SYNONYMS \
             WHERE OWNER = :1 AND SYNONYM_NAME = :2",
            &[
                OracleBindValue::Text(owner.to_string()),
                OracleBindValue::Text(name),
            ],
        )
        .ok()?;
        if let Some(row) = rows.first()
            && let (Some(owner), Some(table)) =
                (oracle_meta_text(row, 0), oracle_meta_text(row, 1))
        {
            return Some((owner, table));
        }
    }
    None
}

/// 身份列声明（`GENERATED ALWAYS|BY DEFAULT AS IDENTITY`）。视图不存在时返回空表，
/// 由 `IDENTITY_COLUMN='YES'` 的兜底文本覆盖。
fn oracle_load_identity_columns(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> std::collections::BTreeMap<String, String> {
    let Ok(rows) = oracle_query(
        connection,
        "SELECT COLUMN_NAME, GENERATION_TYPE FROM ALL_TAB_IDENTITY_COLS \
         WHERE OWNER = :1 AND TABLE_NAME = :2",
        &[
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(table.to_string()),
        ],
    ) else {
        return std::collections::BTreeMap::new();
    };
    rows.iter()
        .filter_map(|row| {
            let name = oracle_meta_text(row, 0)?;
            // `GENERATION_TYPE` 取值 `ALWAYS` / `BY DEFAULT` / `BY DEFAULT ON NULL`。
            let generation = oracle_meta_text(row, 1).unwrap_or_else(|| "BY DEFAULT".into());
            Some((name, format!("GENERATED {generation} AS IDENTITY")))
        })
        .collect()
}

/// 声明类型文本。Oracle 的 `DATA_TYPE` 已经带精度（如 `TIMESTAMP(6) WITH TIME ZONE`），
/// 只有字符类型和 NUMBER 需要按目录字段补齐长度/精度。
fn oracle_column_type_name(
    data_type: &str,
    data_length: u64,
    char_length: u64,
    char_used: &str,
    precision: Option<i64>,
    scale: Option<i64>,
) -> String {
    let upper = data_type.trim().to_ascii_uppercase();
    let base = upper.split('(').next().unwrap_or("").trim().to_string();
    match base.as_str() {
        "CHAR" | "VARCHAR" | "VARCHAR2" | "NCHAR" | "NVARCHAR2" => {
            let length = if char_length > 0 { char_length } else { data_length };
            // `CHAR_USED='C'` 表示长度按字符计，必须显式写 CHAR，否则再建表会变成字节语义。
            let unit = if char_used.eq_ignore_ascii_case("C") {
                " CHAR"
            } else {
                " BYTE"
            };
            format!("{}({length}{unit})", data_type.trim())
        }
        "NUMBER" => match (precision, scale) {
            (Some(precision), Some(scale)) if precision > 0 => {
                format!("NUMBER({precision},{scale})")
            }
            (Some(precision), _) if precision > 0 => format!("NUMBER({precision})"),
            _ => "NUMBER".to_string(),
        },
        _ => data_type.trim().to_string(),
    }
}

fn oracle_indexes_for(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<Vec<IndexInfo>> {
    let schema = oracle_request_schema(config, path)?;
    let connection = oracle_connect(config)?;
    oracle_load_indexes(&connection, &schema, &path.name)
}

fn oracle_load_indexes(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Vec<IndexInfo>> {
    let rows = oracle_query(
        connection,
        "SELECT I.INDEX_NAME, I.UNIQUENESS, I.INDEX_TYPE, IC.COLUMN_NAME, \
                CASE WHEN C.CONSTRAINT_TYPE = 'P' THEN 1 ELSE 0 END AS IS_PK \
         FROM ALL_INDEXES I \
         LEFT JOIN ALL_IND_COLUMNS IC \
           ON IC.INDEX_OWNER = I.OWNER AND IC.INDEX_NAME = I.INDEX_NAME \
         LEFT JOIN ALL_CONSTRAINTS C \
           ON C.OWNER = I.OWNER AND C.INDEX_NAME = I.INDEX_NAME \
          AND C.CONSTRAINT_TYPE IN ('P','U') \
         WHERE I.OWNER = :1 AND I.TABLE_NAME = :2 \
           AND I.INDEX_TYPE <> 'LOB' \
         ORDER BY I.INDEX_NAME, IC.COLUMN_POSITION",
        &[
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(table.to_string()),
        ],
    )?;
    let mut indexes: Vec<IndexInfo> = Vec::new();
    for row in &rows {
        let Some(name) = oracle_meta_text(row, 0) else {
            continue;
        };
        let unique = oracle_meta_text(row, 1)
            .is_some_and(|value| value.eq_ignore_ascii_case("UNIQUE"));
        let index_type = oracle_meta_text(row, 2);
        let column = oracle_meta_text(row, 3);
        let is_primary = oracle_meta_u64(row, 4).unwrap_or(0) != 0;
        // 函数索引在 `ALL_IND_COLUMNS` 里没有列名；列信息缺失的索引无法安全重建，
        // 直接跳过而不是生成 `CREATE INDEX ... ()`。
        if let Some(existing) = indexes.iter_mut().find(|index| index.name == name) {
            if let Some(column) = column {
                existing.columns.push(column);
            }
            continue;
        }
        if column.is_none() {
            continue;
        }
        indexes.push(IndexInfo {
            name,
            columns: column.into_iter().collect(),
            is_unique: unique,
            is_primary,
            index_type,
            comment: None,
        });
    }
    Ok(indexes)
}

fn oracle_foreign_keys_for(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<Vec<ForeignKeyInfo>> {
    let schema = oracle_request_schema(config, path)?;
    let connection = oracle_connect(config)?;
    oracle_load_foreign_keys(&connection, &schema, &path.name)
}

fn oracle_load_foreign_keys(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Vec<ForeignKeyInfo>> {
    Ok(
        oracle_load_foreign_keys_for_tables(connection, schema, &[table.to_string()], &|| false)?
            .into_iter()
            .map(|(_, foreign_key)| foreign_key)
            .collect(),
    )
}

/// 批量读取同一 Owner 下多张表的外键，返回 `(源表名, 外键)`；复合键每列占一行。
///
/// ER 打开整库关系时要读全部表的外键，逐表调用会为每一张表各登录一次（Oracle 登录
/// 含 2 次 `ALTER SESSION`，N+1 代价明显）。这里一次连接、按 `IN` 分批查询；
/// Oracle 的 `IN` 列表上限是 1000 项，故按 [`ORACLE_IN_BATCH`] 切片，
/// 每片之间检查取消。
fn oracle_load_foreign_keys_for_tables(
    connection: &OracleConnection,
    schema: &str,
    tables: &[String],
    should_cancel: &dyn Fn() -> bool,
) -> fluxdb_core::Result<Vec<(String, ForeignKeyInfo)>> {
    let mut out = Vec::new();
    for chunk in tables.chunks(ORACLE_IN_BATCH) {
        if should_cancel() {
            return Ok(out);
        }
        if chunk.is_empty() {
            continue;
        }
        let mut binds = vec![OracleBindValue::Text(schema.to_string())];
        let placeholders = chunk
            .iter()
            .map(|table| oracle_placeholder(&mut binds, OracleBindValue::Text(table.clone())))
            .collect::<Vec<_>>()
            .join(", ");
        let rows = oracle_query(
            connection,
            &format!(
                "SELECT C.TABLE_NAME, C.CONSTRAINT_NAME, CC.COLUMN_NAME, \
                        R.OWNER, R.TABLE_NAME, RCC.COLUMN_NAME \
                 FROM ALL_CONSTRAINTS C \
                 JOIN ALL_CONS_COLUMNS CC \
                   ON CC.OWNER = C.OWNER AND CC.CONSTRAINT_NAME = C.CONSTRAINT_NAME \
                 JOIN ALL_CONSTRAINTS R \
                   ON R.OWNER = C.R_OWNER AND R.CONSTRAINT_NAME = C.R_CONSTRAINT_NAME \
                 JOIN ALL_CONS_COLUMNS RCC \
                   ON RCC.OWNER = R.OWNER AND RCC.CONSTRAINT_NAME = R.CONSTRAINT_NAME \
                  AND RCC.POSITION = CC.POSITION \
                 WHERE C.OWNER = :1 AND C.CONSTRAINT_TYPE = 'R' \
                   AND C.TABLE_NAME IN ({placeholders}) \
                 ORDER BY C.TABLE_NAME, C.CONSTRAINT_NAME, CC.POSITION"
            ),
            &binds,
        )?;
        oracle_group_foreign_key_rows(&rows, &mut out);
    }
    Ok(out)
}

/// 把「源表 + 约束」相同的行合并成一个 [`ForeignKeyInfo`]，复合键按列序累积。
fn oracle_group_foreign_key_rows(
    rows: &[OracleRow],
    out: &mut Vec<(String, ForeignKeyInfo)>,
) {
    for row in rows {
        let Some(table) = oracle_meta_text(row, 0) else {
            continue;
        };
        let Some(name) = oracle_meta_text(row, 1) else {
            continue;
        };
        let column = oracle_meta_text(row, 2).unwrap_or_default();
        let ref_schema = oracle_meta_text(row, 3);
        let ref_table = oracle_meta_text(row, 4).unwrap_or_default();
        let ref_column = oracle_meta_text(row, 5).unwrap_or_default();
        if let Some((_, foreign_key)) = out
            .iter_mut()
            .find(|(source, fk)| source == &table && fk.name == name)
        {
            foreign_key.columns.push(column.clone());
            foreign_key.ref_columns.push(ref_column);
            foreign_key.column = foreign_key
                .columns
                .first()
                .cloned()
                .unwrap_or(column);
            foreign_key.ref_column = foreign_key
                .ref_columns
                .first()
                .cloned()
                .unwrap_or_default();
            continue;
        }
        out.push((
            table,
            ForeignKeyInfo {
                name,
                column: column.clone(),
                ref_schema,
                ref_table,
                ref_column: ref_column.clone(),
                columns: vec![column],
                ref_columns: vec![ref_column],
            },
        ));
    }
}

/// 读取某个 Owner 下的全部表名（不含视图），用于「批量读全库外键」的空表清单。
fn oracle_load_table_names(
    connection: &OracleConnection,
    schema: &str,
) -> fluxdb_core::Result<Vec<String>> {
    let rows = oracle_query(
        connection,
        "SELECT TABLE_NAME FROM ALL_TABLES WHERE OWNER = :1 ORDER BY TABLE_NAME",
        &[OracleBindValue::Text(schema.to_string())],
    )?;
    Ok(rows
        .iter()
        .filter_map(|row| oracle_meta_text(row, 0))
        .collect())
}

/// 批量读取同一 Owner 下多张表的列，供 ER 字段面板与补全使用。
///
/// 与逐表调用等价（同样的列、类型文本、主键标记与注释），但只登录一次。
/// 这里不读身份列/虚拟列：那两项只服务设计表 DDL，补全与 ER 都不需要，
/// 单表路径仍走 [`oracle_load_column_infos`]。
fn oracle_load_completion_columns_for_tables(
    connection: &OracleConnection,
    schema: &str,
    tables: &[String],
    database: Option<&str>,
    should_cancel: &dyn Fn() -> bool,
) -> fluxdb_core::Result<Vec<CompletionColumn>> {
    let mut out = Vec::new();
    for chunk in tables.chunks(ORACLE_IN_BATCH) {
        if should_cancel() {
            return Ok(out);
        }
        if chunk.is_empty() {
            continue;
        }
        // 未引用表名由 SQL 解析得到时可能是小写；Oracle 目录里存的是折叠后的大写名。
        // 同时按原名和折叠名查，返回时再映射回调用方请求的写法，避免索引键对不上。
        let mut lookup = Vec::new();
        for table in chunk {
            lookup.push(table.clone());
            let upper = table.to_uppercase();
            if upper != *table {
                lookup.push(upper);
            }
        }
        lookup.sort();
        lookup.dedup();
        let mut binds = vec![
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(schema.to_string()),
        ];
        let placeholders = lookup
            .iter()
            .map(|table| oracle_placeholder(&mut binds, OracleBindValue::Text(table.clone())))
            .collect::<Vec<_>>()
            .join(", ");
        let rows = oracle_query(
            connection,
            &format!(
                "SELECT C.TABLE_NAME, C.COLUMN_NAME, C.DATA_TYPE, C.DATA_LENGTH, \
                        C.CHAR_LENGTH, C.CHAR_USED, C.DATA_PRECISION, C.DATA_SCALE, \
                        C.NULLABLE, CC.COMMENTS, \
                        CASE WHEN PK.COLUMN_NAME IS NULL THEN 0 ELSE 1 END AS IS_PK \
                 FROM ALL_TAB_COLS C \
                 LEFT JOIN ALL_COL_COMMENTS CC \
                   ON CC.OWNER = C.OWNER AND CC.TABLE_NAME = C.TABLE_NAME \
                  AND CC.COLUMN_NAME = C.COLUMN_NAME \
                 LEFT JOIN (SELECT CO.OWNER, CO.TABLE_NAME, CC2.COLUMN_NAME \
                            FROM ALL_CONSTRAINTS CO \
                            JOIN ALL_CONS_COLUMNS CC2 \
                              ON CC2.OWNER = CO.OWNER AND CC2.CONSTRAINT_NAME = CO.CONSTRAINT_NAME \
                            WHERE CO.CONSTRAINT_TYPE = 'P' AND CO.OWNER = :1) PK \
                   ON PK.OWNER = C.OWNER AND PK.TABLE_NAME = C.TABLE_NAME \
                  AND PK.COLUMN_NAME = C.COLUMN_NAME \
                 WHERE C.OWNER = :2 AND C.HIDDEN_COLUMN = 'NO' \
                   AND C.TABLE_NAME IN ({placeholders}) \
                 ORDER BY C.TABLE_NAME, C.COLUMN_ID"
            ),
            &binds,
        )?;
        for row in &rows {
            let (Some(table), Some(name)) = (oracle_meta_text(row, 0), oracle_meta_text(row, 1))
            else {
                continue;
            };
            let requested = chunk
                .iter()
                .find(|candidate| **candidate == table)
                .or_else(|| {
                    chunk
                        .iter()
                        .find(|candidate| candidate.eq_ignore_ascii_case(&table))
                })
                .cloned()
                .unwrap_or_else(|| table.clone());
            out.push(CompletionColumn {
                database: database.map(str::to_string),
                schema: Some(schema.to_string()),
                table: requested,
                name,
                type_name: Some(oracle_column_type_name(
                    &oracle_meta_text(row, 2).unwrap_or_default(),
                    oracle_meta_u64(row, 3).unwrap_or(0),
                    oracle_meta_u64(row, 4).unwrap_or(0),
                    &oracle_meta_text(row, 5).unwrap_or_default(),
                    oracle_meta_i64(row, 6),
                    oracle_meta_i64(row, 7),
                )),
                nullable: oracle_meta_text(row, 8)
                    .is_some_and(|value| value.eq_ignore_ascii_case("Y")),
                primary_key: oracle_meta_u64(row, 10).unwrap_or(0) != 0,
                comment: oracle_meta_text(row, 9),
                stable: None,
            });
        }
    }
    Ok(out)
}

fn oracle_triggers_for(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<Vec<TriggerInfo>> {
    let schema = oracle_request_schema(config, path)?;
    let connection = oracle_connect(config)?;
    oracle_load_triggers(&connection, &schema, &path.name)
}

fn oracle_load_triggers(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Vec<TriggerInfo>> {
    let rows = oracle_query(
        connection,
        "SELECT TRIGGER_NAME, TRIGGERING_EVENT, TRIGGER_TYPE, TRIGGER_BODY \
         FROM ALL_TRIGGERS WHERE TABLE_OWNER = :1 AND TABLE_NAME = :2 \
         ORDER BY TRIGGER_NAME",
        &[
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(table.to_string()),
        ],
    )?;
    Ok(rows
        .iter()
        .filter_map(|row| {
            let name = oracle_meta_text(row, 0)?;
            let trigger_type = oracle_meta_text(row, 2).unwrap_or_default();
            // `TRIGGER_TYPE` 形如 `BEFORE EACH ROW`；展示层只区分时机。
            let timing = trigger_type
                .split_whitespace()
                .next()
                .unwrap_or_default()
                .to_string();
            Some(TriggerInfo {
                name,
                event: oracle_meta_text(row, 1).unwrap_or_default(),
                timing,
                body: oracle_meta_text(row, 3),
            })
        })
        .collect())
}

fn oracle_table_ddl_for(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<String> {
    let schema = oracle_request_schema(config, path)?;
    let connection = oracle_connect(config)?;
    if path.kind == ObjectKind::View {
        return oracle_view_ddl(&connection, &schema, &path.name);
    }
    let columns = oracle_load_column_infos(&connection, &schema, &path.name)?;
    let indexes = oracle_load_indexes(&connection, &schema, &path.name)?;
    let foreign_keys = oracle_load_foreign_keys(&connection, &schema, &path.name)?;
    let table_comment = oracle_load_table_comment(&connection, &schema, &path.name)?;
    Ok(oracle_render_table_ddl(
        &schema,
        &path.name,
        &columns,
        &indexes,
        &foreign_keys,
        table_comment.as_deref(),
    ))
}

/// 设计表快照：一次登录读全部元数据，避免 UI 打开时多次握手。
fn oracle_load_table_design_metadata(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<fluxdb_core::TableDesignMetadata> {
    oracle_load_table_design_metadata_with_details(config, path, true)
}

fn oracle_load_table_design_base_metadata(
    config: &ConnectionConfig,
    path: &ObjectPath,
) -> fluxdb_core::Result<fluxdb_core::TableDesignMetadata> {
    oracle_load_table_design_metadata_with_details(config, path, false)
}

fn oracle_load_table_design_metadata_with_details(
    config: &ConnectionConfig,
    path: &ObjectPath,
    include_details: bool,
) -> fluxdb_core::Result<fluxdb_core::TableDesignMetadata> {
    let schema = oracle_request_schema(config, path)?;
    let connection = oracle_connect(config)?;
    let columns = oracle_load_column_infos(&connection, &schema, &path.name)?;
    if path.kind == ObjectKind::View {
        let ddl = oracle_view_ddl(&connection, &schema, &path.name)?;
        return Ok(fluxdb_core::TableDesignMetadata {
            columns: oracle_completion_columns(path, &schema, columns),
            indexes: Vec::new(),
            foreign_keys: Vec::new(),
            triggers: Vec::new(),
            ddl,
            details_loaded: true,
        });
    }
    let indexes = if include_details {
        oracle_load_indexes(&connection, &schema, &path.name)?
    } else {
        Vec::new()
    };
    let foreign_keys = if include_details {
        oracle_load_foreign_keys(&connection, &schema, &path.name)?
    } else {
        Vec::new()
    };
    let triggers = if include_details {
        oracle_load_triggers(&connection, &schema, &path.name)?
    } else {
        Vec::new()
    };
    let table_comment = oracle_load_table_comment(&connection, &schema, &path.name)?;
    let ddl = oracle_render_table_ddl(
        &schema,
        &path.name,
        &columns,
        &indexes,
        &foreign_keys,
        table_comment.as_deref(),
    );
    Ok(fluxdb_core::TableDesignMetadata {
        columns: oracle_completion_columns(path, &schema, columns),
        indexes,
        foreign_keys,
        triggers,
        ddl,
        details_loaded: include_details,
    })
}

fn oracle_completion_columns(
    path: &ObjectPath,
    schema: &str,
    columns: Vec<OracleColumnInfo>,
) -> Vec<CompletionColumn> {
    columns
        .into_iter()
        .map(|column| CompletionColumn {
            database: path.database.clone(),
            schema: Some(schema.to_string()),
            table: path.name.clone(),
            name: column.name,
            type_name: Some(column.type_name),
            nullable: column.nullable,
            primary_key: column.primary_key,
            comment: column.comment,
            stable: None,
        })
        .collect()
}

fn oracle_load_table_comment(
    connection: &OracleConnection,
    schema: &str,
    table: &str,
) -> fluxdb_core::Result<Option<String>> {
    let rows = oracle_query(
        connection,
        "SELECT COMMENTS FROM ALL_TAB_COMMENTS WHERE OWNER = :1 AND TABLE_NAME = :2",
        &[
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(table.to_string()),
        ],
    )?;
    Ok(rows.first().and_then(|row| oracle_meta_text(row, 0)))
}

fn oracle_view_ddl(
    connection: &OracleConnection,
    schema: &str,
    view: &str,
) -> fluxdb_core::Result<String> {
    let rows = oracle_query(
        connection,
        "SELECT TEXT FROM ALL_VIEWS WHERE OWNER = :1 AND VIEW_NAME = :2",
        &[
            OracleBindValue::Text(schema.to_string()),
            OracleBindValue::Text(view.to_string()),
        ],
    )?;
    let text = rows
        .first()
        .and_then(|row| oracle_meta_text(row, 0))
        .ok_or_else(|| Error::new(ErrorKind::Query, "未读取到 Oracle 视图定义"))?;
    Ok(format!(
        "CREATE OR REPLACE VIEW {} AS\n{};",
        oracle_qualified_table(schema, view),
        text.trim().trim_end_matches(';').trim_end()
    ))
}

fn oracle_render_table_ddl(
    schema: &str,
    table_name: &str,
    columns: &[OracleColumnInfo],
    indexes: &[IndexInfo],
    foreign_keys: &[ForeignKeyInfo],
    table_comment: Option<&str>,
) -> String {
    let ddl_type = |name: &str| fluxdb_core::OracleDialect.quote_identifier(name);
    let table = oracle_qualified_table(schema, table_name);
    let mut lines = Vec::new();
    for column in columns {
        let mut line = format!("  {} {}", ddl_type(&column.name), column.type_name);
        if let Some(identity) = column.identity.as_deref() {
            line.push(' ');
            line.push_str(identity);
        } else if let Some(expression) = column.virtual_expression.as_deref() {
            line.push_str(&format!(" GENERATED ALWAYS AS ({})", expression.trim()));
        } else if let Some(default_value) = column.default_value.as_deref() {
            line.push_str(&format!(" DEFAULT {}", default_value.trim()));
        }
        // 虚拟列的可空性由表达式决定，不能写 NOT NULL。
        if !column.nullable && column.virtual_expression.is_none() {
            line.push_str(" NOT NULL");
        }
        lines.push(line);
    }
    let pk_columns = columns
        .iter()
        .filter(|column| column.primary_key)
        .map(|column| ddl_type(&column.name))
        .collect::<Vec<_>>();
    if !pk_columns.is_empty() {
        let constraint = columns
            .iter()
            .find_map(|column| column.primary_key_constraint.as_deref())
            .filter(|name| !name.trim().is_empty())
            .map(|name| format!("CONSTRAINT {} ", ddl_type(name)))
            .unwrap_or_default();
        lines.push(format!(
            "  {constraint}PRIMARY KEY ({})",
            pk_columns.join(", ")
        ));
    }
    for foreign_key in foreign_keys {
        if foreign_key.columns.is_empty() || foreign_key.columns.len() != foreign_key.ref_columns.len()
        {
            continue;
        }
        let source = foreign_key
            .columns
            .iter()
            .map(|column| ddl_type(column))
            .collect::<Vec<_>>()
            .join(", ");
        let target = foreign_key
            .ref_columns
            .iter()
            .map(|column| ddl_type(column))
            .collect::<Vec<_>>()
            .join(", ");
        let ref_table = oracle_qualified_table(
            foreign_key.ref_schema.as_deref().unwrap_or(schema),
            &foreign_key.ref_table,
        );
        lines.push(format!(
            "  CONSTRAINT {} FOREIGN KEY ({source}) REFERENCES {ref_table} ({target})",
            ddl_type(&foreign_key.name)
        ));
    }
    let mut ddl = format!("CREATE TABLE {table} (\n{}\n)", lines.join(",\n"));
    for index in indexes
        .iter()
        .filter(|index| !index.is_primary && !index.columns.is_empty())
    {
        let cols = index
            .columns
            .iter()
            .map(|column| ddl_type(column))
            .collect::<Vec<_>>()
            .join(", ");
        ddl.push_str(&format!(
            ";\nCREATE {}INDEX {} ON {table} ({cols})",
            if index.is_unique { "UNIQUE " } else { "" },
            ddl_type(&index.name)
        ));
    }
    if let Some(comment) = table_comment.filter(|comment| !comment.trim().is_empty()) {
        ddl.push_str(&format!(
            ";\nCOMMENT ON TABLE {table} IS {}",
            oracle_string_literal(comment)
        ));
    }
    for column in columns
        .iter()
        .filter(|column| column.comment.as_deref().is_some_and(|c| !c.trim().is_empty()))
    {
        ddl.push_str(&format!(
            ";\nCOMMENT ON COLUMN {table}.{} IS {}",
            ddl_type(&column.name),
            oracle_string_literal(column.comment.as_deref().unwrap_or_default())
        ));
    }
    format!("{ddl};")
}

fn oracle_string_literal(value: &str) -> String {
    format!("'{}'", value.replace('\'', "''"))
}
